function HRG_WA_print_metrics(m)
% HRG_WA_PRINT_METRICS  Pretty-print performance metrics.

fprintf('\n================ ASIC/FPGA interface simulation metrics ================\n');
fprintf('Final input angle          : %10.3f deg\n', m.finalInputAngleDeg);
