    fprintf('Max abs rate error all     : %10.5f deg/s\n', m.maxAbsRateErrorAllDps);
end
fprintf('Mean E                     : %10.6f\n', m.meanE);
fprintf('Std E                      : %10.6g\n', m.stdE);
fprintf('Max |Q|                    : %10.6g\n', m.maxAbsQ);
fprintf('Lock time                  : %10.3f s\n', m.lockTime);
