// ============================================================================
// 详细注释补充说明
// ----------------------------------------------------------------------------
// 本模块实现可综合 CORDIC atan2，用于从 S/R 向量计算驻波角相位。
//
// 输入向量：
//   x_in = R，y_in = S。
// 输出相位：
//   phase 为 32-bit binary-turn，2^32 对应 360°。
//   在 HRG 二阶模态中 phase = 4θ 的相位。
//
// 算法说明：
//   先根据象限修正初始向量和初始相位；
//   再使用旋转模式/向量模式迭代逼近 atan2；
//   atan_lut 中保存 atan(2^-i) 对应的 binary-turn 常数。
// ============================================================================

// ============================================================================
// hrg_cordic_atan2.v
// ----------------------------------------------------------------------------
// 功能：
//   可综合 CORDIC 向量模式 atan2 计算模块。
//   输入为已解调得到的 R、S 两个正交量，输出 phi = atan2(S,R)。
//   相位采用 binary-turn 格式：
//      32'h0000_0000 = 0 turn = 0 deg
//      32'h4000_0000 = 1/4 turn = 90 deg
//      32'h8000_0000 = 1/2 turn = 180 deg 或 -180 deg
//      32'hFFFF_FFFF ≈ -1 LSB
//
// 说明：
//   1. 本模块是逐次迭代结构，ITER=32 时延约 32 个 clk。
//   2. start 拉高 1 拍后，busy 拉高；valid 拉高 1 拍时 phase 有效。
//   3. 该模块不使用 real、不使用 initial 表达式初始化寄存器，适合综合。
//   4. atan_lut 为常量查找表，单位为 32-bit binary-turn。
// ============================================================================

`timescale 1ns/1ps

module hrg_cordic_atan2 #(
    parameter IN_W  = 32,
    parameter XY_W  = 36,
    parameter ITER  = 32
)(
    input                       clk,
    input                       rst_n,

    input                       start,
    input      signed [IN_W-1:0] x_in,   // R 分量
    input      signed [IN_W-1:0] y_in,   // S 分量

    output reg                  busy,
    output reg                  valid,
    output reg        [31:0]    phase    // atan2(S,R), binary-turn
);

    reg signed [XY_W-1:0] x_reg;
    reg signed [XY_W-1:0] y_reg;
    reg        [31:0]     z_reg;
    reg        [5:0]      iter_cnt;

    wire signed [XY_W-1:0] x_shift = x_reg >>> iter_cnt;
    wire signed [XY_W-1:0] y_shift = y_reg >>> iter_cnt;

    // atan(2^-i) / (2*pi) * 2^32
    function [31:0] atan_lut;
        input [5:0] idx;
        begin
            case (idx)
            6'd 0: atan_lut = 32'h20000000;
            6'd 1: atan_lut = 32'h12E4051E;
            6'd 2: atan_lut = 32'h09FB385B;
            6'd 3: atan_lut = 32'h051111D4;
            6'd 4: atan_lut = 32'h028B0D43;
            6'd 5: atan_lut = 32'h0145D7E1;
            6'd 6: atan_lut = 32'h00A2F61E;
            6'd 7: atan_lut = 32'h00517C55;
            6'd 8: atan_lut = 32'h0028BE53;
            6'd 9: atan_lut = 32'h00145F2F;
            6'd10: atan_lut = 32'h000A2F98;
            6'd11: atan_lut = 32'h000517CC;
            6'd12: atan_lut = 32'h00028BE6;
            6'd13: atan_lut = 32'h000145F3;
            6'd14: atan_lut = 32'h0000A2FA;
            6'd15: atan_lut = 32'h0000517D;
            6'd16: atan_lut = 32'h000028BE;
            6'd17: atan_lut = 32'h0000145F;
            6'd18: atan_lut = 32'h00000A30;
            6'd19: atan_lut = 32'h00000518;
            6'd20: atan_lut = 32'h0000028C;
            6'd21: atan_lut = 32'h00000146;
            6'd22: atan_lut = 32'h000000A3;
            6'd23: atan_lut = 32'h00000051;
            6'd24: atan_lut = 32'h00000029;
            6'd25: atan_lut = 32'h00000014;
            6'd26: atan_lut = 32'h0000000A;
            6'd27: atan_lut = 32'h00000005;
            6'd28: atan_lut = 32'h00000003;
            6'd29: atan_lut = 32'h00000001;
            6'd30: atan_lut = 32'h00000001;
            6'd31: atan_lut = 32'h00000000;
            default: atan_lut = 32'h00000000;
            endcase
        end
    endfunction

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            x_reg    <= {XY_W{1'b0}};
            y_reg    <= {XY_W{1'b0}};
            z_reg    <= 32'd0;
            iter_cnt <= 6'd0;
            busy     <= 1'b0;
            valid    <= 1'b0;
            phase    <= 32'd0;
        end else begin
            valid <= 1'b0;

            if (start && !busy) begin
                // 预旋转处理 x<0 的象限，使 CORDIC 收敛区间覆盖 atan2 全平面。
                // 若 (x,y) 在左半平面，则把向量取反，并给相位加 180 度。
                if (x_in[IN_W-1]) begin
                    x_reg <= -{{(XY_W-IN_W){x_in[IN_W-1]}}, x_in};
                    y_reg <= -{{(XY_W-IN_W){y_in[IN_W-1]}}, y_in};
                    z_reg <= 32'h8000_0000;
                end else begin
                    x_reg <=  {{(XY_W-IN_W){x_in[IN_W-1]}}, x_in};
                    y_reg <=  {{(XY_W-IN_W){y_in[IN_W-1]}}, y_in};
                    z_reg <= 32'h0000_0000;
                end
                iter_cnt <= 6'd0;
                busy     <= 1'b1;
            end else if (busy) begin
                // CORDIC vectoring mode:
                // 目标是把 y_reg 旋转到 0，同时累计旋转角 z_reg。
                if (!y_reg[XY_W-1]) begin
                    x_reg <= x_reg + y_shift;
                    y_reg <= y_reg - x_shift;
                    z_reg <= z_reg + atan_lut(iter_cnt);
                end else begin
                    x_reg <= x_reg - y_shift;
                    y_reg <= y_reg + x_shift;
                    z_reg <= z_reg - atan_lut(iter_cnt);
                end

                if (iter_cnt == ITER-1) begin
                    busy     <= 1'b0;
                    valid    <= 1'b1;
                    phase    <= z_reg;
                    iter_cnt <= 6'd0;
                end else begin
                    iter_cnt <= iter_cnt + 6'd1;
                end
            end
        end
    end

endmodule

b7957d3302815cdb1e5b9ce03a5f7a84217a372d.text:
// ============================================================================
// 详细注释补充说明
// ----------------------------------------------------------------------------
// 本模块实现 HRG 检测链路的数字解调前端，输入为载波级 x/y 原始 ADC。
//
// 同步解调数学关系：
//   Cx = LPF(2*x*cos_ref)，Sx = LPF(2*x*sin_ref)
//   Cy = LPF(2*y*cos_ref)，Sy = LPF(2*y*sin_ref)
//   E  = Cx^2 + Sx^2 + Cy^2 + Sy^2
//   Q  = 2*(Cx*Sy - Cy*Sx)
//   R  = Cx^2 + Sx^2 - Cy^2 - Sy^2
//   S  = 2*(Cx*Cy + Sx*Sy)
//
// 结构说明：
//   1) NCO 产生与谐振载波同频的 sin/cos 参考；
//   2) IQ mixer 完成 x/y 与 sin/cos 的乘法混频；
//   3) CIC 完成大倍率抽取和第一级低通；
//   4) FIR5 进一步平滑解调后的基带慢变量；
//   5) sat_shl1 对 LPF 平均因子进行 2 倍幅值补偿；
//   6) hrg_eqsr_calc 输出后级控制所需 E/Q/S/R。
// ============================================================================

// ============================================================================
// hrg_demod_frontend.v
// ----------------------------------------------------------------------------
// HRG 原始 X/Y 采样到 E/Q/S/R 的完整数字解调前端。
//
// 链路：
//   原始 ADC x/y
//   -> NCO sin/cos 参考
//   -> IQ 混频 x*cos, x*sin, y*cos, y*sin
//   -> 三阶 CIC 低通抽取
//   -> 五抽头 FIR 低通
//   -> 乘 2 补偿同步解调的 1/2 平均因子
//   -> E/Q/S/R 计算
//
// 默认 raw_valid 采样率为 64 kHz，DECIM_R=64 后输出 1 kHz 慢变量。
// ============================================================================

`timescale 1ns/1ps

module hrg_demod_frontend #(
    parameter ADC_W      = 16,
    parameter DATA_W     = 32,
    parameter FRAC       = 30,
    parameter DECIM_R    = 64,
    parameter CIC_SHIFT  = 18
)(
    input                         clk,
    input                         rst_n,
    input                         raw_valid,
    input signed [ADC_W-1:0]      adc_x,
    input signed [ADC_W-1:0]      adc_y,
    input        [31:0]           cfg_nco_phase_inc,
    input        [31:0]           cfg_nco_phase_offset,

    output                        eqsr_valid,
    output signed [DATA_W-1:0]    e_out,
    output signed [DATA_W-1:0]    q_out,
    output signed [DATA_W-1:0]    s_out,
    output signed [DATA_W-1:0]    r_out,

    output signed [DATA_W-1:0]    dbg_cx,
    output signed [DATA_W-1:0]    dbg_sx,
    output signed [DATA_W-1:0]    dbg_cy,
    output signed [DATA_W-1:0]    dbg_sy,
    output signed [15:0]          dbg_sin_ref,
    output signed [15:0]          dbg_cos_ref
);

    wire signed [15:0] sin_ref;
    wire signed [15:0] cos_ref;
    wire ref_valid;
    wire [31:0] phase_acc_unused;

    hrg_nco_sincos u_nco (
        .clk(clk),
        .rst_n(rst_n),
        .en(raw_valid),
        .phase_inc(cfg_nco_phase_inc),
        .phase_offset(cfg_nco_phase_offset),
        .sin_ref(sin_ref),
        .cos_ref(cos_ref),
        .ref_valid(ref_valid),
        .phase_acc(phase_acc_unused)
    );

    assign dbg_sin_ref = sin_ref;
    assign dbg_cos_ref = cos_ref;

    wire mix_valid;
    wire signed [DATA_W-1:0] mix_xi, mix_xq, mix_yi, mix_yq;

    hrg_iq_mixer #(
        .ADC_W(ADC_W),
        .REF_W(16),
        .OUT_W(DATA_W)
    ) u_mix (
        .clk(clk),
        .rst_n(rst_n),
        .in_valid(ref_valid),
        .adc_x(adc_x),
        .adc_y(adc_y),
        .sin_ref(sin_ref),
        .cos_ref(cos_ref),
        .out_valid(mix_valid),
        .x_i(mix_xi),
        .x_q(mix_xq),
        .y_i(mix_yi),
        .y_q(mix_yq)
    );

    wire cic_v_xi, cic_v_xq, cic_v_yi, cic_v_yq;
    wire signed [DATA_W-1:0] cic_xi, cic_xq, cic_yi, cic_yq;

    hrg_cic_decimator #(.IN_W(DATA_W), .ACC_W(64), .OUT_W(DATA_W), .DECIM_R(DECIM_R), .GAIN_SHIFT(CIC_SHIFT)) u_cic_xi (
        .clk(clk), .rst_n(rst_n), .in_valid(mix_valid), .din(mix_xi), .out_valid(cic_v_xi), .dout(cic_xi));
    hrg_cic_decimator #(.IN_W(DATA_W), .ACC_W(64), .OUT_W(DATA_W), .DECIM_R(DECIM_R), .GAIN_SHIFT(CIC_SHIFT)) u_cic_xq (
        .clk(clk), .rst_n(rst_n), .in_valid(mix_valid), .din(mix_xq), .out_valid(cic_v_xq), .dout(cic_xq));
    hrg_cic_decimator #(.IN_W(DATA_W), .ACC_W(64), .OUT_W(DATA_W), .DECIM_R(DECIM_R), .GAIN_SHIFT(CIC_SHIFT)) u_cic_yi (
        .clk(clk), .rst_n(rst_n), .in_valid(mix_valid), .din(mix_yi), .out_valid(cic_v_yi), .dout(cic_yi));
    hrg_cic_decimator #(.IN_W(DATA_W), .ACC_W(64), .OUT_W(DATA_W), .DECIM_R(DECIM_R), .GAIN_SHIFT(CIC_SHIFT)) u_cic_yq (
        .clk(clk), .rst_n(rst_n), .in_valid(mix_valid), .din(mix_yq), .out_valid(cic_v_yq), .dout(cic_yq));

    wire fir_v_xi, fir_v_xq, fir_v_yi, fir_v_yq;
    wire signed [DATA_W-1:0] fir_xi, fir_xq, fir_yi, fir_yq;

    hrg_fir5_lpf #(.DATA_W(DATA_W)) u_fir_xi (.clk(clk), .rst_n(rst_n), .in_valid(cic_v_xi), .din(cic_xi), .out_valid(fir_v_xi), .dout(fir_xi));
    hrg_fir5_lpf #(.DATA_W(DATA_W)) u_fir_xq (.clk(clk), .rst_n(rst_n), .in_valid(cic_v_xq), .din(cic_xq), .out_valid(fir_v_xq), .dout(fir_xq));
    hrg_fir5_lpf #(.DATA_W(DATA_W)) u_fir_yi (.clk(clk), .rst_n(rst_n), .in_valid(cic_v_yi), .din(cic_yi), .out_valid(fir_v_yi), .dout(fir_yi));
    hrg_fir5_lpf #(.DATA_W(DATA_W)) u_fir_yq (.clk(clk), .rst_n(rst_n), .in_valid(cic_v_yq), .din(cic_yq), .out_valid(fir_v_yq), .dout(fir_yq));

    function signed [DATA_W-1:0] sat_shl1;
        input signed [DATA_W-1:0] v;
        begin
            // 左移 1 位前先判断是否会超出 signed 32-bit 范围。
            if (v > 32'sh3fff_ffff)
                sat_shl1 = 32'sh7fff_ffff;
            else if (v < -32'sh4000_0000)
                sat_shl1 = 32'sh8000_0000;
            else
                sat_shl1 = v <<< 1;
        end
    endfunction

    wire signed [DATA_W-1:0] cx = sat_shl1(fir_xi);
    wire signed [DATA_W-1:0] sx = sat_shl1(fir_xq);
    wire signed [DATA_W-1:0] cy = sat_shl1(fir_yi);
    wire signed [DATA_W-1:0] sy = sat_shl1(fir_yq);

    assign dbg_cx = cx;
    assign dbg_sx = sx;
    assign dbg_cy = cy;
    assign dbg_sy = sy;

    hrg_eqsr_calc #(
        .DATA_W(DATA_W),
        .FRAC(FRAC)
    ) u_eqsr (
        .clk(clk),
        .rst_n(rst_n),
        .in_valid(fir_v_xi & fir_v_xq & fir_v_yi & fir_v_yq),
        .cx(cx),
        .sx(sx),
        .cy(cy),
        .sy(sy),
        .out_valid(eqsr_valid),
        .e_out(e_out),
        .q_out(q_out),
        .s_out(s_out),
        .r_out(r_out)
    );

endmodule

68f25ea39bd2931c5b0dd6bac45d51aa20c89d38.text:
// ============================================================================
// 详细注释补充说明
// ----------------------------------------------------------------------------
// 本模块由四路同步解调基带量 Cx/Sx/Cy/Sy 计算全角模式慢变量。
//
// 物理含义：
//   E：谐振能量，用于能量闭环；
//   Q：正交误差，用于正交闭环；
//   S/R：驻波角解算向量，atan2(S,R)=4θ。
//
// 定点处理：
//   输入为 Q2.30，乘法得到 Q4.60；右移 FRAC 后回到 Q2.30。
//   sat_q30 用于防止中间运算超过 32-bit 输出范围。
// ============================================================================

// ============================================================================
// hrg_eqsr_calc.v
// ----------------------------------------------------------------------------
// 根据同步解调后的四个慢变量 Cx/Sx/Cy/Sy 计算 HRG 全角模式 E/Q/S/R。
//
// 输入 Cx/Sx/Cy/Sy 格式：signed Q2.30。
// 输出 E/Q/S/R 格式：signed Q2.30。
//
// 数学关系：
//   E = Cx^2 + Sx^2 + Cy^2 + Sy^2
//   Q = 2*(Cx*Sy - Cy*Sx)
//   R = Cx^2 + Sx^2 - Cy^2 - Sy^2
//   S = 2*(Cx*Cy + Sx*Sy)
//
// 对二阶模态 HRG，atan2(S,R) = 4*theta。
// ============================================================================

`timescale 1ns/1ps

module hrg_eqsr_calc #(
    parameter DATA_W = 32,
    parameter FRAC   = 30
)(
    input                         clk,
    input                         rst_n,
    input                         in_valid,
    input signed [DATA_W-1:0]     cx,
    input signed [DATA_W-1:0]     sx,
    input signed [DATA_W-1:0]     cy,
    input signed [DATA_W-1:0]     sy,
    output reg                    out_valid,
    output reg signed [DATA_W-1:0] e_out,
    output reg signed [DATA_W-1:0] q_out,
    output reg signed [DATA_W-1:0] s_out,
    output reg signed [DATA_W-1:0] r_out
);

    wire signed [63:0] cx2_w = ($signed(cx) * $signed(cx)) >>> FRAC;
    wire signed [63:0] sx2_w = ($signed(sx) * $signed(sx)) >>> FRAC;
    wire signed [63:0] cy2_w = ($signed(cy) * $signed(cy)) >>> FRAC;
    wire signed [63:0] sy2_w = ($signed(sy) * $signed(sy)) >>> FRAC;

    wire signed [63:0] cxsy_w = ($signed(cx) * $signed(sy)) >>> FRAC;
    wire signed [63:0] cysx_w = ($signed(cy) * $signed(sx)) >>> FRAC;
    wire signed [63:0] cxcy_w = ($signed(cx) * $signed(cy)) >>> FRAC;
    wire signed [63:0] sxsy_w = ($signed(sx) * $signed(sy)) >>> FRAC;

    wire signed [63:0] e_w = cx2_w + sx2_w + cy2_w + sy2_w;
    wire signed [63:0] q_w = (cxsy_w - cysx_w) <<< 1;
    wire signed [63:0] r_w = cx2_w + sx2_w - cy2_w - sy2_w;
    wire signed [63:0] s_w = (cxcy_w + sxsy_w) <<< 1;

    function signed [DATA_W-1:0] sat_q30;
        input signed [63:0] v;
        begin
            if (v > 64'sh0000_0000_7fff_ffff)
                sat_q30 = 32'sh7fff_ffff;
            else if (v < 64'shffff_ffff_8000_0000)
                sat_q30 = 32'sh8000_0000;
            else
                sat_q30 = v[DATA_W-1:0];
        end
    endfunction

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 1'b0;
            e_out <= {DATA_W{1'b0}};
            q_out <= {DATA_W{1'b0}};
            s_out <= {DATA_W{1'b0}};
            r_out <= {DATA_W{1'b0}};
        end else begin
            out_valid <= in_valid;
            if (in_valid) begin
                e_out <= sat_q30(e_w);
                q_out <= sat_q30(q_w);
                s_out <= sat_q30(s_w);
                r_out <= sat_q30(r_w);
            end
        end
    end

endmodule

cf5d7b92ff7b9b2955b88f2a250c193267e6e236.text:
// ============================================================================
// 详细注释补充说明
// ----------------------------------------------------------------------------
// 本模块完成同步解调的乘法混频。
//
// 输入：
//   adc_x/adc_y：原始检测信号，signed Q1.15。
//   sin_ref/cos_ref：NCO 参考，signed Q1.15。
//
// 输出：
//   x_i = x*cos_ref，x_q = x*sin_ref
//   y_i = y*cos_ref，y_q = y*sin_ref
// 输出扩展到 DATA_W 位，保留足够动态范围，后续 CIC/FIR 负责低通抽取。
// ============================================================================

// ============================================================================
// hrg_iq_mixer.v
// ----------------------------------------------------------------------------
// 双通道同步 IQ 混频器。
//
// 输入：
//   adc_x, adc_y : signed Q1.15 原始检测采样
//   sin_ref/cos_ref : signed Q1.15 NCO 参考
//
// 输出：
//   x_i = x*cos, x_q = x*sin, y_i = y*cos, y_q = y*sin
//   格式为 signed Q2.30，后级 CIC/FIR 低通后乘 2 得到 Cx/Sx/Cy/Sy。
// ============================================================================

`timescale 1ns/1ps

module hrg_iq_mixer #(
    parameter ADC_W = 16,
    parameter REF_W = 16,
    parameter OUT_W = 32
)(
    input                         clk,
    input                         rst_n,
    input                         in_valid,
    input signed [ADC_W-1:0]      adc_x,
    input signed [ADC_W-1:0]      adc_y,
    input signed [REF_W-1:0]      sin_ref,
    input signed [REF_W-1:0]      cos_ref,
    output reg                    out_valid,
    output reg signed [OUT_W-1:0] x_i,
    output reg signed [OUT_W-1:0] x_q,
    output reg signed [OUT_W-1:0] y_i,
    output reg signed [OUT_W-1:0] y_q
);

    wire signed [ADC_W+REF_W-1:0] x_cos_mul = $signed(adc_x) * $signed(cos_ref);
    wire signed [ADC_W+REF_W-1:0] x_sin_mul = $signed(adc_x) * $signed(sin_ref);
    wire signed [ADC_W+REF_W-1:0] y_cos_mul = $signed(adc_y) * $signed(cos_ref);
    wire signed [ADC_W+REF_W-1:0] y_sin_mul = $signed(adc_y) * $signed(sin_ref);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 1'b0;
            x_i <= {OUT_W{1'b0}};
            x_q <= {OUT_W{1'b0}};
            y_i <= {OUT_W{1'b0}};
            y_q <= {OUT_W{1'b0}};
        end else begin
            out_valid <= in_valid;
            if (in_valid) begin
                x_i <= x_cos_mul[OUT_W-1:0];
                x_q <= x_sin_mul[OUT_W-1:0];
                y_i <= y_cos_mul[OUT_W-1:0];
                y_q <= y_sin_mul[OUT_W-1:0];
            end
        end
    end

endmodule

3d7413b4a02797b0871d161299309bff28a57c04.text:
// ============================================================================
// 详细注释补充说明
// ----------------------------------------------------------------------------
// 本模块完成从 CORDIC phase=4θ 到全角输出角和角速度的转换。
//
// 功能流程：
//   1) phase_valid 有效时进行相位展开，消除 0/2π 回绕；
//   2) 由 4θ 得到 θ，即右移 2 位；
//   3) zero_angle 脉冲在进入 RUN 时记录参考角，实现输出清零；
//   4) 使用 cfg_cbyran_inv_q28 做 Bryan 因子反标度；
//   5) 差分得到速率，再用一阶 IIR 低通抑制角度量化噪声。
// ============================================================================

// ============================================================================
// hrg_phase_angle_rate.v
// ----------------------------------------------------------------------------
// 功能：
//   1. 对 CORDIC 输出的 phi=atan2(S,R) 进行相位展开。
//   2. 根据全角模式关系 phi = 4*theta，得到驻波角 theta。
//   3. 在进入 RUN 状态时建立 theta_ref，使输出角度清零。
//   4. 按 Bryan 因子反推输入转角。
//   5. 对角度差分得到速率，并进行一阶低通滤波。
// 
// 相位单位：
//   phase/angle 均采用 binary-turn，2^32 LSB = 1 turn = 360 deg。
//   angle_out 为 signed 64-bit，单位仍是 binary-turn 扩展格式。
//   rate_out 为 signed Q16.16，单位 deg/s。
// ============================================================================

`timescale 1ns/1ps

module hrg_phase_angle_rate #(
    parameter RATE_SCALE_Q32 = 64'd23592960000   // Fs=1000Hz 时，deg/s Q16 = dturn32 * RATE_SCALE_Q32 / 2^32
)(
    input                   clk,
    input                   rst_n,

    input                   phase_valid,
    input        [31:0]     phi_phase,

    input                   zero_angle,             // 进入 RUN 时拉高 1 拍
    input      signed [31:0] cfg_cbyran_inv_q28,    // 1/cB，Q4.28
    input             [15:0] cfg_rate_lpf_alpha_q16,// 速率低通 alpha，Q0.16

    output reg signed [63:0] phi_ext,
    output reg signed [63:0] theta_ext,
    output reg signed [63:0] angle_out,
    output reg signed [31:0] rate_out,
    output reg               angle_valid,
    output reg               angle_jump
);

    reg                 phase_init;
    reg        [31:0]   phi_prev;
    reg signed [63:0]  theta_ref;
    reg signed [63:0]  angle_prev;

    wire [31:0]         phi_diff_u = phi_phase - phi_prev;
    wire signed [31:0]  phi_diff_s = phi_diff_u;

    wire signed [63:0]  phi_ext_next   = phase_init ? (phi_ext + {{32{phi_diff_s[31]}}, phi_diff_s}) :
                                                      {{32{phi_phase[31]}}, phi_phase};
    wire signed [63:0]  theta_ext_next = phi_ext_next >>> 2;

    wire signed [63:0]  theta_delta = theta_ext_next - theta_ref;

    // 64-bit theta_delta 乘以 32-bit Q4.28 增益，结果为 96-bit。
    wire signed [31:0]  inv_cbyran_q28_s = cfg_cbyran_inv_q28;
    wire signed [95:0]  angle_mul = $signed(theta_delta) * $signed(inv_cbyran_q28_s);
    wire signed [63:0]  angle_calc = -(angle_mul >>> 28);

    wire signed [63:0]  angle_diff = angle_calc - angle_prev;
    wire signed [127:0] rate_mul   = angle_diff * $signed(RATE_SCALE_Q32);
    wire signed [63:0]  rate_raw64 = rate_mul >>> 32;

    wire signed [63:0]  rate_err64 = rate_raw64 - {{32{rate_out[31]}}, rate_out};
    wire signed [80:0]  rate_lpf_mul = rate_err64 * $signed({1'b0, cfg_rate_lpf_alpha_q16});
    wire signed [63:0]  rate_step64 = rate_lpf_mul >>> 16;
    wire signed [63:0]  rate_filt64 = {{32{rate_out[31]}}, rate_out} + rate_step64;

    function signed [31:0] sat32;
        input signed [63:0] v;
        begin
            if (v > 64'sh0000_0000_7fff_ffff)
                sat32 = 32'sh7fff_ffff;
            else if (v < 64'shffff_ffff_8000_0000)
                sat32 = 32'sh8000_0000;
            else
                sat32 = v[31:0];
        end
    endfunction

    // 用于粗略检测异常相位跳变。
    // 对 phi=4theta 而言，正常采样周期内不应接近半周跳变。
    wire large_phase_step = phase_init && (phi_diff_s > 32'sh3000_0000 || phi_diff_s < -32'sh3000_0000);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase_init <= 1'b0;
            phi_prev   <= 32'd0;
            phi_ext    <= 64'sd0;
            theta_ext  <= 64'sd0;
            theta_ref  <= 64'sd0;
            angle_out  <= 64'sd0;
            angle_prev <= 64'sd0;
            rate_out   <= 32'sd0;
            angle_valid<= 1'b0;
            angle_jump <= 1'b0;
        end else begin
            angle_valid <= 1'b0;

            if (phase_valid) begin
                phase_init <= 1'b1;
                phi_prev   <= phi_phase;
                phi_ext    <= phi_ext_next;
                theta_ext  <= theta_ext_next;
                angle_valid<= 1'b1;

                if (zero_angle) begin
                    theta_ref  <= theta_ext_next;
                    angle_out  <= 64'sd0;
                    angle_prev <= 64'sd0;
                    rate_out   <= 32'sd0;
                end else begin
                    angle_out  <= angle_calc;
                    angle_prev <= angle_calc;
                    rate_out   <= sat32(rate_filt64);
                end

                if (large_phase_step) begin
                    angle_jump <= 1'b1;
                end
            end
        end
    end

endmodule

