// ============================================================================
// 详细注释补充说明
// ----------------------------------------------------------------------------
// 本模块是通用定点 PI 控制器，可用于能量环和正交环。
//
// 计算关系：
//   p_term = kp * err
//   i_acc  = i_acc + ki * err
//   out    = sat((p_term + i_acc) >> FRAC)
//
// 限幅设计：
//   integ_limit 限制积分器，防止长期误差导致 wind-up；
//   out_limit 限制输出控制量，模拟 DAC/驱动最大幅值。
// ============================================================================

// ============================================================================
// hrg_pi_ctrl.v
// ----------------------------------------------------------------------------
// 功能：
//   可综合定点 PI 控制器，带积分限幅、输出限幅和饱和标志。
//   用于半球谐振陀螺全角模式的能量环 E 和正交环 Q 控制。
// 
// 定点格式建议：
//   err、out、out_limit：Q2.30
//   kp、ki：Q2.30
//   integ：内部 64-bit，保持更多余量
//
// 控制律：
//   p_term = kp * err
//   integ  = integ + ki * err
//   out    = sat(p_term + integ)
// ============================================================================

`timescale 1ns/1ps

module hrg_pi_ctrl #(
    parameter DATA_W = 32,
    parameter GAIN_W = 32,
    parameter ACC_W  = 64,
    parameter FRAC   = 30
)(
    input                         clk,
    input                         rst_n,

    input                         en,
    input                         clear,

    input      signed [DATA_W-1:0] err,
    input      signed [GAIN_W-1:0] kp,
    input      signed [GAIN_W-1:0] ki,
    input      signed [DATA_W-1:0] out_limit,
    input      signed [ACC_W-1:0]  integ_limit,

    output reg signed [DATA_W-1:0] out,
    output reg signed [ACC_W-1:0]  integ,
    output reg                     sat
);

    wire signed [DATA_W+GAIN_W-1:0] p_mult = err * kp;
    wire signed [DATA_W+GAIN_W-1:0] i_mult = err * ki;

    wire signed [ACC_W-1:0] p_term = p_mult >>> FRAC;
    wire signed [ACC_W-1:0] i_step = i_mult >>> FRAC;

    reg signed [ACC_W-1:0] integ_next;
    reg signed [ACC_W-1:0] integ_try;
    reg signed [ACC_W-1:0] sum_try;
    reg signed [ACC_W-1:0] sum_next;
    reg signed [ACC_W-1:0] pos_lim_ext;
    reg signed [ACC_W-1:0] neg_lim_ext;
    reg signed [DATA_W-1:0] pos_lim;
    reg signed [DATA_W-1:0] neg_lim;
    reg                     hold_integ;

    always @(*) begin
        pos_lim = out_limit;
        neg_lim = -out_limit;
        pos_lim_ext = {{(ACC_W-DATA_W){pos_lim[DATA_W-1]}}, pos_lim};
        neg_lim_ext = {{(ACC_W-DATA_W){neg_lim[DATA_W-1]}}, neg_lim};

        // 积分器候选值先按原 PI 关系累加，再按 integ_limit 限幅。
        integ_try = integ + i_step;
        if (integ_try > integ_limit) begin
            integ_try = integ_limit;
        end else if (integ_try < -integ_limit) begin
            integ_try = -integ_limit;
        end

        // 抗积分饱和：
        // 当输出已经将要撞正限幅且误差仍为正时，继续积分只会把积分器推得更深，
        // 因此保持积分器；负限幅同理。若误差方向有利于退出饱和，则允许积分器回退。
        sum_try = p_term + integ_try;
        hold_integ = 1'b0;
        if ((sum_try > pos_lim_ext) && (err > 0)) begin
            hold_integ = 1'b1;
        end else if ((sum_try < neg_lim_ext) && (err < 0)) begin
            hold_integ = 1'b1;
        end

        if (hold_integ) begin
            integ_next = integ;
        end else begin
            integ_next = integ_try;
        end

        sum_next = p_term + integ_next;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out   <= {DATA_W{1'b0}};
            integ <= {ACC_W{1'b0}};
            sat   <= 1'b0;
        end else if (clear) begin
            out   <= {DATA_W{1'b0}};
            integ <= {ACC_W{1'b0}};
            sat   <= 1'b0;
        end else if (en) begin
            integ <= integ_next;
            sat   <= 1'b0;

            if (sum_next > {{(ACC_W-DATA_W){pos_lim[DATA_W-1]}}, pos_lim}) begin
                out <= pos_lim;
                sat <= 1'b1;
            end else if (sum_next < {{(ACC_W-DATA_W){neg_lim[DATA_W-1]}}, neg_lim}) begin
                out <= neg_lim;
                sat <= 1'b1;
            end else begin
                out <= sum_next[DATA_W-1:0];
            end
        end
    end

endmodule

0b4437fae4a469d8dd5ebe83b20b07d4e968a915.text:
// ============================================================================
// 详细注释补充说明
// ----------------------------------------------------------------------------
// 本模块是 HRG 全角模式数字控制核心，输入为已解调好的 E/Q/S/R。
//
// 控制回路：
//   e_err = E_set - E，用于能量 PI，输出 fa；
//   q_err = Q_set - Q，用于正交 PI，输出 fq。
//
// 角度链路：
//   CORDIC 计算 phi=atan2(S,R)，对二阶模态有 phi=4θ；
//   hrg_phase_angle_rate 完成 4θ 展相、RUN 清零、Bryan 因子补偿和速率估计。
//
// 状态机：
//   MODE_IDLE：关闭或复位；
//   MODE_LOCK：等待 E/Q 达到锁定条件并计数；
//   MODE_RUN ：输出有效角度/速率，并锁存运行期故障。
// ============================================================================

// ============================================================================
// hrg_wa_if_top.v
// ----------------------------------------------------------------------------
// 半球谐振陀螺 HRG 全角模式 ASIC/FPGA 数字控制接口顶层。
// 
// 该顶层面向“已完成同步解调后的 E/Q/S/R 数据”。
// 输入：
//   adc_e, adc_q, adc_s, adc_r  均为 signed Q2.30
// 输出：
//   dac_fa, dac_fq              能量环和正交环控制量，signed Q2.30
//   angle_out                   全角模式积分角，signed binary-turn 扩展格式
//   rate_out                    角速度，signed Q16.16 deg/s
//
// 主要功能：
//   1. 状态机：IDLE -> LOCK -> RUN
//   2. E 能量 PI 闭环
//   3. Q 正交 PI 闭环
//   4. CORDIC atan2(S,R)
//   5. 4theta 相位展开
//   6. RUN 状态输出清零与角度积分
//   7. 状态字与故障标志
//
// 状态字 status_word：
//   bit0  data_ready
//   bit1  locked/RUN
//   bit2  ADC saturation sticky
//   bit3  DAC saturation sticky
//   bit4  fixed-point saturation sticky
//   bit5  angle jump sticky
//   bit6  E fault sticky
//   bit7  Q fault sticky
// ============================================================================

`timescale 1ns/1ps

module hrg_wa_if_top #(
    parameter DATA_W = 32,
    parameter FRAC   = 30,
    parameter LOCK_SAMPLES = 1000,
    parameter signed [DATA_W-1:0] ADC_SAT_POS = 32'sh7fff_ffff,
    parameter signed [DATA_W-1:0] ADC_SAT_NEG = 32'sh8000_0000
)(
    input                         clk,
    input                         rst_n,

    input                         cfg_enable,
    input                         cfg_clear_fault,

    input                         adc_valid,
    input signed [DATA_W-1:0]     adc_e,
    input signed [DATA_W-1:0]     adc_q,
    input signed [DATA_W-1:0]     adc_s,
    input signed [DATA_W-1:0]     adc_r,

    input signed [DATA_W-1:0]     cfg_e_set,
    input signed [DATA_W-1:0]     cfg_q_set,

    input signed [DATA_W-1:0]     cfg_kp_e,
    input signed [DATA_W-1:0]     cfg_ki_e,
    input signed [DATA_W-1:0]     cfg_kp_q,
    input signed [DATA_W-1:0]     cfg_ki_q,

    input signed [DATA_W-1:0]     cfg_fa_limit,
    input signed [DATA_W-1:0]     cfg_fq_limit,
    input signed [63:0]           cfg_integ_limit,

    input signed [31:0]           cfg_cbyran_inv_q28,
    input        [15:0]           cfg_rate_lpf_alpha_q16,

    input signed [DATA_W-1:0]     cfg_lock_e_tol,
    input signed [DATA_W-1:0]     cfg_lock_q_tol,
    input signed [DATA_W-1:0]     cfg_e_fault_low,
    input signed [DATA_W-1:0]     cfg_e_fault_high,
    input signed [DATA_W-1:0]     cfg_q_fault_abs,

    output                        dac_valid,
    output signed [DATA_W-1:0]    dac_fa,
    output signed [DATA_W-1:0]    dac_fq,

    output signed [63:0]          angle_out,
    output signed [31:0]          rate_out,
    output                        data_ready,

    output reg [1:0]              mode,
    output reg [31:0]             status_word
);

    localparam MODE_IDLE = 2'd1;
    localparam MODE_LOCK = 2'd2;
    localparam MODE_RUN  = 2'd3;

    function signed [DATA_W-1:0] abs32;
        input signed [DATA_W-1:0] v;
        begin
            abs32 = v[DATA_W-1] ? -v : v;
        end
    endfunction

    wire signed [DATA_W-1:0] e_err = cfg_e_set - adc_e;
    wire signed [DATA_W-1:0] q_err = cfg_q_set - adc_q;

    wire e_good = (abs32(e_err) < cfg_lock_e_tol);
    wire q_good = (abs32(adc_q) < cfg_lock_q_tol);

    wire e_fault_now = (adc_e < cfg_e_fault_low) || (adc_e > cfg_e_fault_high);
    wire q_fault_now = (abs32(adc_q) > cfg_q_fault_abs);

    wire adc_sat_now = (adc_e == ADC_SAT_POS) || (adc_e == ADC_SAT_NEG) ||
                       (adc_q == ADC_SAT_POS) || (adc_q == ADC_SAT_NEG) ||
                       (adc_s == ADC_SAT_POS) || (adc_s == ADC_SAT_NEG) ||
                       (adc_r == ADC_SAT_POS) || (adc_r == ADC_SAT_NEG);

    reg [31:0] lock_cnt;
    reg        zero_angle_pulse;

    // ------------------------------------------------------------------------
    // PI 控制器
    // ------------------------------------------------------------------------
    wire signed [DATA_W-1:0] fa_pi;
    wire signed [DATA_W-1:0] fq_pi;
    wire signed [63:0]       integ_e;
    wire signed [63:0]       integ_q;
    wire                     fa_sat;
    wire                     fq_sat;

    // LOCK -> RUN 时会产生 zero_angle_pulse。该时刻同时清除 PI 积分器，
    // 避免 LOCK 阶段启动瞬态把正交环积分器推到限幅，导致进入 RUN 后 fq_sat 常高。
    wire                     pi_clear = (!cfg_enable) || zero_angle_pulse;

    hrg_pi_ctrl #(
        .DATA_W(DATA_W),
        .GAIN_W(DATA_W),
        .ACC_W(64),
        .FRAC(FRAC)
    ) u_pi_e (
        .clk(clk),
        .rst_n(rst_n),
        .en(adc_valid && cfg_enable),
        .clear(pi_clear),
        .err(e_err),
        .kp(cfg_kp_e),
        .ki(cfg_ki_e),
        .out_limit(cfg_fa_limit),
        .integ_limit(cfg_integ_limit),
        .out(fa_pi),
        .integ(integ_e),
        .sat(fa_sat)
    );

    hrg_pi_ctrl #(
        .DATA_W(DATA_W),
        .GAIN_W(DATA_W),
        .ACC_W(64),
        .FRAC(FRAC)
    ) u_pi_q (
        .clk(clk),
        .rst_n(rst_n),
        .en(adc_valid && cfg_enable),
        .clear(pi_clear),
        .err(q_err),
        .kp(cfg_kp_q),
        .ki(cfg_ki_q),
        .out_limit(cfg_fq_limit),
        .integ_limit(cfg_integ_limit),
        .out(fq_pi),
        .integ(integ_q),
        .sat(fq_sat)
    );

    assign dac_fa    = fa_pi;
    assign dac_fq    = fq_pi;
    assign dac_valid = adc_valid && (mode != MODE_IDLE);

    // ------------------------------------------------------------------------
    // CORDIC angle calculation
    // ------------------------------------------------------------------------
    wire cordic_busy;
    wire cordic_valid;
    wire [31:0] phi_phase;

    // S/R 向量有效性判断，避免 atan2(0,0) 引起随机角。
    wire vector_ok = (abs32(adc_s) > 32'sd1024) || (abs32(adc_r) > 32'sd1024);
    wire cordic_start = adc_valid && vector_ok && !cordic_busy && cfg_enable;

    hrg_cordic_atan2 u_cordic (
        .clk(clk),
        .rst_n(rst_n),
        .start(cordic_start),
        .x_in(adc_r),
        .y_in(adc_s),
        .busy(cordic_busy),
        .valid(cordic_valid),
        .phase(phi_phase)
    );

    wire signed [63:0] phi_ext_dbg;
    wire signed [63:0] theta_ext_dbg;
    wire angle_valid;
    wire angle_jump;

    hrg_phase_angle_rate u_phase (
        .clk(clk),
        .rst_n(rst_n),
        .phase_valid(cordic_valid),
        .phi_phase(phi_phase),
        .zero_angle(zero_angle_pulse),
        .cfg_cbyran_inv_q28(cfg_cbyran_inv_q28),
        .cfg_rate_lpf_alpha_q16(cfg_rate_lpf_alpha_q16),
        .phi_ext(phi_ext_dbg),
        .theta_ext(theta_ext_dbg),
        .angle_out(angle_out),
        .rate_out(rate_out),
        .angle_valid(angle_valid),
        .angle_jump(angle_jump)
    );

    assign data_ready = angle_valid;

    // ------------------------------------------------------------------------
    // 状态机与 sticky fault
    // ------------------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mode             <= MODE_IDLE;
            lock_cnt         <= 32'd0;
            zero_angle_pulse <= 1'b0;
            status_word      <= 32'd0;
        end else begin
            zero_angle_pulse <= 1'b0;

            if (cfg_clear_fault) begin
                status_word[31:2] <= 30'd0;
            end

            if (!cfg_enable) begin
                mode      <= MODE_IDLE;
                lock_cnt  <= 32'd0;
                status_word[1:0] <= 2'b00;
            end else begin
                case (mode)
                    MODE_IDLE: begin
                        mode     <= MODE_LOCK;
                        lock_cnt <= 32'd0;
                    end

                    MODE_LOCK: begin
                        if (adc_valid) begin
                            if (e_good && q_good) begin
                                if (lock_cnt >= LOCK_SAMPLES-1) begin
                                    mode             <= MODE_RUN;
                                    zero_angle_pulse <= 1'b1;
                                    lock_cnt         <= 32'd0;
                                end else begin
                                    lock_cnt <= lock_cnt + 32'd1;
                                end
                            end else begin
                                lock_cnt <= 32'd0;
                            end
                        end
                    end

                    MODE_RUN: begin
                        mode <= MODE_RUN;
                    end

                    default: begin
                        mode <= MODE_IDLE;
                    end
                endcase

                status_word[0] <= angle_valid;
                status_word[1] <= (mode == MODE_RUN);

                // sticky fault 只在 RUN 状态下锁存，避免启动瞬态污染最终状态。
                if (mode == MODE_RUN) begin
                    if (adc_sat_now)          status_word[2] <= 1'b1;
                    if (fa_sat || fq_sat)     status_word[3] <= 1'b1;
                    if (angle_jump)           status_word[5] <= 1'b1;
                    if (e_fault_now)          status_word[6] <= 1'b1;
                    if (q_fault_now)          status_word[7] <= 1'b1;
                end
            end
        end
    end

endmodule

e86a6f37ce245a364725d3bedc311064068150b9.text:
// ============================================================================
// 详细注释补充说明
// ----------------------------------------------------------------------------
// 本文件是 testbench 使用的慢变量 HRG plant 模型，不参与综合。
//
// 作用：
//   直接根据 fa/fq 控制量推进 E、Q、θ 状态；
//   生成 E/Q/S/R 慢变量，供 hrg_wa_if_top 闭环验证。
//
// 与 full_frontend testbench 的区别：
//   本模型绕过 NCO/IQ/CIC/FIR，只验证控制核心；
//   hrg_wa_raw_plant_model.sv 则输出原始 x/y 载波采样，用于完整前端验证。
// ============================================================================

// ============================================================================
// hrg_wa_plant_model.sv
// ----------------------------------------------------------------------------
// 行为级 HRG 全角模式慢变量 plant。
// 该文件用于 testbench，不可综合。
// 
// 状态：
//   E      能量变量
//   Q      正交变量
//   theta  物理驻波角，rad
//
// 模型：
//   dE/dt     = -2*damp*E + fa
//   dQ/dt     = -2*damp*Q - 2*dOmega*E*sin(4*(theta-thetaOmega)) + fq
//   dtheta/dt = -cBryan*inputRate
//              + 0.5*dTau*sin(4*(theta-thetaTau))
//              + 0.5*dOmega*(Q/E)*cos(4*(theta-thetaOmega))
//
// 输出：
//   E_adc, Q_adc, S_adc, R_adc，均转成 Q2.30 给 RTL。
// ============================================================================

`timescale 1ns/1ps

module hrg_wa_plant_model;

    real E;
    real Q;
    real theta;

    real cBryan;
    real damp;
    real dOmega;
    real dTau;
    real thetaOmega;
    real thetaTau;

    initial begin
        E          = 1.0;
        Q          = 0.0;
        theta      = 0.0;

        cBryan     = 0.300;
        damp       = 0.015;
        dOmega     = 0.0020;
        dTau       = 0.0006;
        thetaOmega = 0.35;
        thetaTau   = 0.20;
    end

    task step;
        input real dt;
        input real input_rate_rad_s;
        input real fa;
        input real fq;
        real Edot;
        real Qdot;
        real Tdot;
        begin
            Edot = -2.0*damp*E + fa;
            Qdot = -2.0*damp*Q
                   - 2.0*dOmega*E*$sin(4.0*(theta-thetaOmega))
                   + fq;

            if (E < 0.05) begin
                Tdot = -cBryan*input_rate_rad_s;
            end else begin
                Tdot = -cBryan*input_rate_rad_s
                       + 0.5*dTau*$sin(4.0*(theta-thetaTau))
                       + 0.5*dOmega*(Q/E)*$cos(4.0*(theta-thetaOmega));
            end

            E     = E     + Edot*dt;
            Q     = Q     + Qdot*dt;
            theta = theta + Tdot*dt;

            if (E < 0.10) E = 0.10;
            if (E > 1.50) E = 1.50;
            if (Q >  0.30) Q =  0.30;
            if (Q < -0.30) Q = -0.30;
        end
    endtask

    task get_eqsr;
        output real Eout;
        output real Qout;
        output real Sout;
        output real Rout;
        real D;
        begin
            D = E*E - Q*Q;
            if (D < 0.0) D = 0.0;
            D = $sqrt(D);

            Eout = E;
            Qout = Q;
            Sout = D*$sin(4.0*theta);
            Rout = D*$cos(4.0*theta);
        end
    endtask

endmodule

