`timescale 1ns/1ps

module tb_hrg_sensor_if;
    logic clk=0, nrst=0;
    logic adc_valid;
    logic signed [17:0] adc_x, adc_y;
    logic signed [13:0] temperature;
    logic spi_sclk=0, spi_csn=1, spi_mosi=0;
    wire spi_miso;
    wire signed [15:0] dac_energy, dac_quad, dac_virtual;
    wire nav_valid;
    wire signed [47:0] angle_out;
    wire signed [31:0] rate_out;
    wire [31:0] status;
    integer sample_index, nav_count, errors;

    always #5 clk = ~clk;

    hrg_sensor_if_top dut (
        .clk(clk), .nrst(nrst), .adc_valid_i(adc_valid),
        .adc_x_i(adc_x), .adc_y_i(adc_y), .temperature_i(temperature),
        .spi_sclk_i(spi_sclk), .spi_csn_i(spi_csn), .spi_mosi_i(spi_mosi),
        .spi_miso_o(spi_miso), .dac_energy_o(dac_energy),
        .dac_quad_o(dac_quad), .dac_virtual_o(dac_virtual),
        .nav_valid_o(nav_valid), .angle_o(angle_out), .rate_o(rate_out),
        .status_o(status)
    );

    task automatic spi_byte(input logic [7:0] tx, output logic [7:0] rx);
        integer b;
        begin
            rx = 0;
            for (b=7; b>=0; b=b-1) begin
                spi_mosi = tx[b];
                #50; spi_sclk = 1;
                #1; rx[b] = spi_miso;
                #49; spi_sclk = 0;
            end
        end
    endtask

    task automatic spi_write(input logic [6:0] addr, input logic [7:0] data);
        logic [7:0] dummy;
        begin
            spi_csn = 0;
            spi_byte({1'b0,addr}, dummy);
            spi_byte(data, dummy);
            #100; spi_csn = 1;
            #1000;
        end
    endtask

    task automatic drive_adc_sample(input integer idx);
        begin
            // 5 kHz coherent carrier at 40 kS/s, spatial amplitudes 0.8/0.6.
            case (idx & 7)
                0: begin adc_x= 18'sd52429; adc_y= 18'sd39322; end
                1: begin adc_x= 18'sd37073; adc_y= 18'sd27805; end
                2: begin adc_x= 18'sd0;     adc_y= 18'sd0;     end
                3: begin adc_x=-18'sd37073; adc_y=-18'sd27805; end
                4: begin adc_x=-18'sd52429; adc_y=-18'sd39322; end
                5: begin adc_x=-18'sd37073; adc_y=-18'sd27805; end
                6: begin adc_x= 18'sd0;     adc_y= 18'sd0;     end
                default: begin adc_x=18'sd37073; adc_y=18'sd27805; end
            endcase
            @(negedge clk); adc_valid=1;
            @(negedge clk); adc_valid=0;
            repeat(23) @(negedge clk);
        end
    endtask

    always @(posedge clk) if (nav_valid) nav_count <= nav_count + 1;

    initial begin
        adc_valid=0; adc_x=0; adc_y=0; temperature=14'sd2500;
        nav_count=0; errors=0;
        repeat(8) @(posedge clk);
        nrst=1;

        // Original SPIRegPG2 protocol: write byte instruction then data byte.
        spi_write(7'h00, 8'h0f); // global, energy, quadrature, virtual enables
        if (dut.ctrl_byte !== 8'h0f) begin
            $error("SPI write did not reach page-0 CTRL byte"); errors=errors+1;
        end

        for (sample_index=0; sample_index<16000; sample_index=sample_index+1)
            drive_adc_sample(sample_index);
        repeat(100) @(posedge clk);

        if (nav_count < 300) begin
            $error("Too few navigation outputs: %0d",nav_count); errors=errors+1;
        end
        if ($signed(dut.energy) < 32'sd11744051 ||
            $signed(dut.energy) > 32'sd21810381) begin
            $error("Steady energy outside 0.7..1.3 Q24: %0d",$signed(dut.energy));
            errors=errors+1;
        end
        if (dut.dsp_overflow !== 1'b0) begin
            $error("Unexpected fixed-point overflow"); errors=errors+1;
        end
        if (!status[6] || !status[22] || !status[23]) begin
            $error("Expected phase-valid/bittrue/pipeline status bits: %h",status);
            errors=errors+1;
        end
        if ($signed(dut.phase4) < 24'sd2000000 ||
            $signed(dut.phase4) > 24'sd5000000) begin
            $error("CORDIC phase outside expected quadrant: %0d",$signed(dut.phase4));
            errors=errors+1;
        end

        if (errors==0) $display("HRG_SENSOR_IF_TB PASS nav=%0d E=%0d phase4=%0d",
                                nav_count,$signed(dut.energy),$signed(dut.phase4));
        else $fatal(1,"HRG_SENSOR_IF_TB FAIL errors=%0d",errors);
        $finish;
    end

    initial begin
        #10000000;
        $fatal(1,"Test timeout");
    end
endmodule

93c4b495f9cc6e72dd4028d7f50b5011e4e8be38.text:
module AsyncFifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 8
)
(
    input wclk,
    input wNrst,

    input wEn,
    input [WIDTH - 1 : 0] wData,
    output full,

    input rclk,
    input rNrst,

    input rEn,
    output [WIDTH - 1 : 0] rData,
    output empty

);
    localparam ADDR_WIDTH = DEPTH == 1 ? 1 : $clog2(DEPTH);

    wire fifoNrst = wNrst & rNrst;

    wire memWEn;
    wire [ADDR_WIDTH - 1 : 0] wAddr;
    wire [ADDR_WIDTH - 1 : 0] rAddr;
    FIFO_TPRAM #(
        .WIDTH(WIDTH),
        .DEPTH(2**ADDR_WIDTH)
    ) instRAM (
        .nrst(fifoNrst),
        .wclk(wclk),

        .wEn(memWEn),
        .wAddr(wAddr),
        .wData(wData),

        .rAddr(rAddr),
        .rData(rData)
    );

    wire [ADDR_WIDTH : 0] rIdx;
    reg [ADDR_WIDTH : 0] rIdxWSync;
    reg [ADDR_WIDTH : 0] rIdxSync;
    wire [ADDR_WIDTH : 0] wIdx;
    reg [ADDR_WIDTH : 0] wIdxRSync;
    reg [ADDR_WIDTH : 0] wIdxSync;

    always @(posedge wclk or negedge fifoNrst) begin
        if(!fifoNrst) begin
            rIdxWSync <= 0;
            rIdxSync <= 0;
        end
        else begin
            rIdxWSync <= rIdx;
            rIdxSync <= rIdxWSync;
        end
    end

    always @(posedge rclk or negedge fifoNrst) begin
        if(!fifoNrst) begin
            wIdxRSync <= 0;
            wIdxSync <= 0;
        end
        else begin
            wIdxRSync <= wIdx;
            wIdxSync <= wIdxRSync;
        end
    end

    WCtrl #(
        .DEPTH(2**ADDR_WIDTH)
    ) instWCtlr (
        .wclk(wclk),
        .wNrst(fifoNrst),

        .rIdx(rIdxSync),
        .wIdx(wIdx),
        .wAddr(wAddr),
        .memWEn(memWEn),

        .wEn(wEn),
        .wFull(full)
    );

    RCtrl #(
        .DEPTH(2**ADDR_WIDTH)
    ) instRCtrl (
        .rclk(rclk),
        .rNrst(fifoNrst),

        .wIdx(wIdxSync),
        .rIdx(rIdx),
        .rAddr(rAddr),

        .rEn(rEn),
        .rEmpty(empty)
    );
endmodule

ff6e73932b095192da22c4178db7fc2b0e7d053e.text:
////////////////////////////////////////////////////////////////////////////////
//  Module      : crc8_param
//  Description : Parameterizable CRC-8 module with fixed-length input.
//                Computes an 8-bit CRC checksum over BYTES bytes (BYTES*8 bits)
//                of input data in a single clock cycle using combinational logic.
//                Fully synthesizable, no registers inferred.
//
//  Parameters:
//    POLYNOMIAL  - CRC-8 generator polynomial (default: 0x07 = x^8 + x^2 + x + 1)
//    INIT_VALUE  - Initial CRC seed value (default: 0x00)
//    BYTES       - Fixed input data width in bytes (default: 32, range: 4~32)
//
//  Ports:
//    data_in     - Input data bus, BYTES*8 bits wide.
//                  Big-endian natural byte order:
//                    First byte processed     at data_in[BYTES*8-1 : BYTES*8-8] (MSB)
//                    ...
//                    Last byte processed      at data_in[7:0] (LSB)
//                  e.g. "123456789" → data_in = {8'h31, 8'h32, ..., 8'h39}
//    crc_out     - 8-bit CRC checksum output (combinational)
////////////////////////////////////////////////////////////////////////////////

module crc8_param #(
    parameter POLYNOMIAL = 8'h07,     // CRC-8 polynomial: x^8 + x^2 + x + 1
    parameter INIT_VALUE = 8'h00,     // Initial CRC register value
    parameter BYTES      = 32         // Fixed input data width in bytes (4 ~ 32)
) (
    input  wire [BYTES*8-1:0] data_in,      // Input data, big-endian natural byte order
    output wire [7:0]         crc_out        // 8-bit CRC result
);

    //----------------------------------------------------------------------
    // Function: crc8_process_byte
    // Process a single byte through the CRC-8 LFSR.
    // Implements one full 8-bit shift of the CRC engine.
    //----------------------------------------------------------------------
    function [7:0] crc8_process_byte;
        input [7:0] current_crc;     // Current CRC accumulator
        input [7:0] data_byte;       // Input data byte
        input [7:0] poly;            // Generator polynomial
        integer bit_idx;
        reg [7:0] result;
        begin
            result = current_crc ^ data_byte;
            for (bit_idx = 0; bit_idx < 8; bit_idx = bit_idx + 1) begin
                if (result[7])
                    result = {result[6:0], 1'b0} ^ poly;
                else
                    result = {result[6:0], 1'b0};
            end
            crc8_process_byte = result;
        end
    endfunction

    //----------------------------------------------------------------------
    // Function: crc8_compute
    // Compute CRC-8 over fixed-length input data (BYTES bytes).
    // First byte (at MSB) is processed first; last byte (at LSB) is last.
    // This matches the natural Verilog bit order where MSB=left, LSB=right.
    // The loop is fully unrolled during synthesis, producing a purely
    // combinational circuit — no registers, no byte_length mux overhead.
    //----------------------------------------------------------------------
    function [7:0] crc8_compute;
        input [BYTES*8-1:0] data;        // Full data bus
        integer byte_idx;
        reg [7:0] crc_accum;
        begin
            crc_accum = INIT_VALUE;
            // Process from MSB to LSB: byte (BYTES-1) first, byte 0 last
            for (byte_idx = BYTES-1; byte_idx >= 0; byte_idx = byte_idx - 1) begin
                crc_accum = crc8_process_byte(crc_accum,
                                              data[byte_idx*8 +: 8],
                                              POLYNOMIAL);
            end
            crc8_compute = crc_accum;
        end
    endfunction

    //----------------------------------------------------------------------
    // Combinational output assignment
    //----------------------------------------------------------------------
    assign crc_out = crc8_compute(data_in);

endmodule

b584609398d4e96df072fab38fe2743aaad06a8d.text:
module FIFO_TPRAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 8
)
(
    input nrst,
    input wclk,

    input wEn,
    input [DEPTH==1 ? 0 : ($clog2(DEPTH) - 1) : 0] wAddr,
    input [WIDTH - 1 : 0] wData,

    input [DEPTH==1 ? 0 : ($clog2(DEPTH) - 1) : 0] rAddr,
    output reg [WIDTH - 1 : 0] rData
);
    reg [WIDTH - 1 : 0] mem[DEPTH - 1 : 0];

    integer i;
    always @(posedge wclk or negedge nrst) begin
        if(!nrst) begin
            for(i = 0; i < DEPTH; i = i + 1)
                mem[i] <= 0;
        end
        else begin
            if(wEn) begin
                mem[wAddr] <= wData;
            end
        end
    end

    always @(*) begin
        rData = mem[rAddr];
    end
endmodule

2634c8b3de12feddb19fb16324b7949589dc09ee.text:
module RCtrl #(
    parameter DEPTH = 8,
    parameter ADDR_WIDTH = DEPTH == 1 ? 1 : $clog2(DEPTH)
)
(
    input rclk,
    input rNrst,

    input [ADDR_WIDTH : 0] wIdx,
    output [ADDR_WIDTH : 0] rIdx,
    output [ADDR_WIDTH - 1 : 0] rAddr,

    input rEn,
    output rEmpty
);
    reg [ADDR_WIDTH : 0] rPtr;

    assign rAddr = rPtr[ADDR_WIDTH - 1 : 0];
    assign rIdx = (rPtr >> 1) ^ rPtr; // gray code

    always @(posedge rclk or negedge rNrst) begin
        if(!rNrst) begin
            rPtr <= 0;
        end
        else begin
            if(rEn && !rEmpty)
                rPtr <= rPtr + 1;
        end
    end

    assign rEmpty = (wIdx == rIdx);
endmodule

d20aa3248c733e3114d0659960cca26156542a8d.text:
module ROReg #(
    parameter READ_OUT_SIZE = (3 + 2 + 2) * 8
)
(
    input sysClk,
    input nrst,

    // config
    input realTimeNEn,
    input [1:0] readOutRealtimeMode,

    input roRegWEn,  // sync with sysclk
    input [119 : 0] roRegWData,  // sync with sysclk
    output roRegFull,

    input readOutWEn,  // sync with sysclk
    input [READ_OUT_SIZE - 1 : 0] readOutWData,  // sync with sysclk
    output readOutFull,

    input lockData,  // must be sample by two sysClk period.
    input roRegREn,  // must be sample by two sysClk period.
    input readOutREn,  // must be sample by two sysClk period.
    output reg [119 : 0] regData,
    output reg [READ_OUT_SIZE - 1 : 0] readOutData
);
    reg roRegFifoREn;
    wire [119:0] roRegFifoRData;
    wire roRegFifoEmpty;
    AsyncFifo #(
        .WIDTH(120),
        .DEPTH(4)
    ) instRoRegFifo (
        .wclk(sysClk),
        .wNrst(nrst),

        .wEn(roRegWEn),
        .wData(roRegWData),
        .full(roRegFull),

        .rclk(sysClk),
        .rNrst(nrst),

        .rEn(roRegFifoREn),
        .rData(roRegFifoRData),
        .empty(roRegFifoEmpty)
    );

    reg readOutFifoREn;
    wire [READ_OUT_SIZE - 1 : 0] readOutFifoRData;
    wire readOutFifoEmpty;

    reg [READ_OUT_SIZE-1 : 0] readOutFIFOWData;
    reg readOutFIFOWEn;
    wire readOutFIFOFull;
    assign readOutFull = 0;
    AsyncFifo #(
        .WIDTH(READ_OUT_SIZE),
        .DEPTH(4)
    ) instReadOutFifo (
        .wclk(sysClk),
        .wNrst(nrst),

        .wEn(readOutFIFOWEn),
        .wData(readOutFIFOWData),
        .full(readOutFIFOFull),

        .rclk(sysClk),
        .rNrst(nrst),

        .rEn(readOutFifoREn),
        .rData(readOutFifoRData),
        .empty(readOutFifoEmpty)
    );

    // write & pop overflow
    reg popEn;
    reg popDone;
    reg writeDone;
    always @(posedge sysClk or negedge nrst) begin
        if(!nrst) begin
            popEn <= 0;
            writeDone <= 0;

            readOutFIFOWData <= 0;
            readOutFIFOWEn <= 0;
        end
        else begin
            if(readOutWEn) begin
                if(!readOutFIFOFull) begin
                    readOutFIFOWData <= readOutWData;
                    readOutFIFOWEn <= 1;
                    writeDone <= 1;
                end
                else begin
                    if(readOutRealtimeMode[1]) begin
                        popEn <= 1;
                        writeDone <= 0;
                        readOutFIFOWData <= readOutWData;
                    end
                    else begin
                        popEn <= 0;
                        writeDone <= 1;
                        readOutFIFOWData <= readOutWData;
                    end
                end
            end
            else if (!writeDone) begin
                if(popDone)
                    popEn <= 0;

                if(!readOutFIFOFull) begin
                    readOutFIFOWEn <= 1;
                    writeDone <= 1;
                end
            end
            else begin
                readOutFIFOWEn <= 0;
            end
        end
    end

    reg [1:0] roRegREnReg;
    reg [1:0] readOutREnReg;
    reg [1:0] lockDataReg;
    always @(posedge sysClk or negedge nrst) begin
        if(!nrst) begin
            roRegREnReg <= 0;
            lockDataReg <= 0;
            readOutREnReg <= 0;
        end
        else begin
            roRegREnReg <= {roRegREnReg[0], roRegREn};
            lockDataReg <= {lockDataReg[0], lockData};
            readOutREnReg <= {readOutREnReg[0], readOutREn};
        end
    end

    reg regReaded;
    always @(posedge sysClk or negedge nrst) begin
        if(!nrst) begin
            regData <= 0;
            roRegFifoREn <= 0;

            regReaded <= 1;
        end
        else begin
            if(lockDataReg == 2'b11) begin
                regData <= regData;
                roRegFifoREn <= 0;
                if(!regReaded && roRegREnReg == 2'b11) begin
                    regReaded <= 1;
                end
                else begin
                    regReaded <= regReaded;
                end
            end
            else begin
                if( (!roRegFifoEmpty) && (regReaded || ~realTimeNEn)) begin
                    regReaded <= 0;
                    regData <= roRegFifoREn ? regData : roRegFifoRData;
                    roRegFifoREn <= roRegFifoREn ? 0 : 1;
                end
                else begin
                    regReaded <= regReaded;
                    regData <= regData;
                    roRegFifoREn <= 0;
                end
            end
        end
    end

    wire [7:0] CRC_E7;
    wire [7:0] CRC_E6;
    crc8_param #(
        .POLYNOMIAL (8'h07),
        .INIT_VALUE (8'h00),
        .BYTES      ((READ_OUT_SIZE/8) - 1)
    )crc_e7_inst(
        .data_in({8'hE7, readOutFifoRData[READ_OUT_SIZE - 9 : 8]}),
        .crc_out(CRC_E7)
    );
    crc8_param #(
        .POLYNOMIAL (8'h07),
        .INIT_VALUE (8'h00),
        .BYTES      ((READ_OUT_SIZE/8) - 1)
    )crc_e6_inst(
        .data_in({8'hE6, readOutFifoRData[READ_OUT_SIZE - 9 : 8]}),
        .crc_out(CRC_E6)
    );

    reg readOutReaded;
    always @(posedge sysClk or negedge nrst) begin
        if(!nrst) begin
            readOutData <= 0;
            readOutFifoREn <= 0;

            readOutReaded <= 1;
            popDone <= 0;
        end
        else begin
            if(lockDataReg == 2'b11) begin
                readOutData <= readOutData;
                readOutFifoREn <= 0;

                if(!readOutReaded && readOutREnReg == 2'b11)
                    readOutReaded <= 1;
                else
                    readOutReaded <= readOutReaded;
            end
            else begin
                if(readOutReaded) begin
                    if(!readOutFifoEmpty) begin
                        readOutData <= {8'hE7, readOutFifoRData[READ_OUT_SIZE - 9 : 8], CRC_E7};
                        readOutReaded <= 0;
                        readOutFifoREn <= 1;
                    end
                    else begin
                        readOutData <= {8'hE6, readOutData[READ_OUT_SIZE - 9 : 8], CRC_E6};
                        readOutReaded <= readOutReaded;
                        readOutFifoREn <= 0;
                    end
                end
                else if(readOutRealtimeMode[0]) begin
                    if(popDone) begin
                        if(!readOutFIFOFull)
                            popDone <= 0;
                        readOutFifoREn <= 0;
                        readOutData <= readOutData;
                    end
                    else if(popEn) begin
                        readOutData <= {8'hE7, readOutFifoRData[READ_OUT_SIZE - 9 : 8], CRC_E7};
                        readOutFifoREn <= 1;
                        popDone <= 1;
                    end
                    else begin
                        popDone <= 0;
                        readOutData <= readOutData;
                        readOutFifoREn <= 0;
                    end
                end
                else begin
                    if(!readOutFifoEmpty) begin
                        readOutData <= {8'hE7, readOutFifoRData[READ_OUT_SIZE - 9 : 8], CRC_E7};
                        readOutReaded <= 0;
                        readOutFifoREn <= 1;
                    end
                    else begin
                        readOutFifoREn <= 0;
                    end
                end
            end
        end
    end
endmodule

9e10345a341638ef9bd9cf6f9ab928df1f8fa4d6.text:
module RWRegPG2 (
    input sysClk,
    input nrst,

    // SPI Write
    input wFifoClk,
    output wFifoFull,
    input wFifowEn,
    input [15:0] wData, // addr + data

    // Int Write
    input intWEn,
    input intREn,
    input intPageSel,
    input [15:0] intWData, // addr + data
    output reg intWDone,
    input intUsePgReg,

    input [7:0] rAddr,
    output reg [7:0] rData,

    output [112*8 - 1:0] configRegPG0,
    output [112*8 - 1:0] configRegPG1,
    output [112*8 - 1:0] configRegPG2,

    output [15*8 - 1 : 0] exConfigReg // base 0x71
);
    reg [7:0] regFile [2:0][111:0];
    // pageCtrl: exRegFile[0][0x70]
    reg [7:0] exRegFile [15:0];

    reg fifoREn;
    wire [15:0] fifoRData;
    wire fifoEmpty;
    AsyncFifo #(
        .WIDTH(16),
        .DEPTH(16)
    ) instFifo (
        .wclk(wFifoClk),
        .wNrst(nrst),

        .wEn(wFifowEn),
        .wData(wData),
        .full(wFifoFull),

        .rclk(sysClk),
        .rNrst(nrst),

        .rEn(fifoREn),
        .rData(fifoRData),
        .empty(fifoEmpty)
    );

    reg regWEn;
    reg [7:0] regWData;
    reg [7:0] addr;
    reg [3:0] exAddr;
    reg [1:0] regWPage;
    reg isExReg;
    always @(posedge sysClk or negedge nrst) begin
        if(!nrst) begin
            regWEn <= 0;
            fifoREn <= 0;

            regWData <= 0;
            addr <= 0;
            exAddr <= 0;
            regWPage <= 0;
            isExReg <= 0;

            intWDone <= 0;
        end
        else begin
            if(!fifoREn && intWEn && ~intWDone) begin
                regWEn <= 1;

                regWData <= intWData[7:0];
                addr <= {1'b0, intWData[14:8]};
                exAddr <= intWData[11:8];
                regWPage <= intUsePgReg ? exRegFile[0][1:0] : {1'b0, intPageSel};
                isExReg <= intWData[14:8] < 7'h70 ? 0 : 1;

                intWDone <= 1;
            end
            else if(!fifoREn && !fifoEmpty && !intWEn) begin
                regWEn <= 1;

                regWData <= fifoRData[7:0];
                addr <= {1'b0, fifoRData[14:8]};
                exAddr <= fifoRData[11:8];
                regWPage <= exRegFile[0][1:0];
                isExReg <= fifoRData[14:8] < 7'h70 ? 0 : 1;

                intWDone <= 0;
            end
            else begin
                intWDone <= 0;
                regWEn <= 0;
            end

            if(fifoREn == 1)
                fifoREn <= 0;
            else if(!fifoEmpty && !intWEn) begin
                fifoREn <= 1;
            end
            else begin
                fifoREn <= 0;
            end
        end
    end

    /**** write Reg ****/
    integer i;
    integer k;
    always @(posedge sysClk or negedge nrst ) begin
        if(!nrst) begin
            for(k = 0; k < 3; k = k + 1) begin
                for(i = 0; i < 112; i = i + 1)
                    regFile[k][i] <= 0;
            end
            for(i = 0; i < 16; i = i + 1)
                exRegFile[i] <= 0;
        end
        else begin
            if(regWEn) begin
                if(isExReg)
                    exRegFile[exAddr] <= regWData[7:0];
                else if(addr < 8'h70) begin
                    if(regWPage <= 2)
                        regFile[regWPage][addr] <= regWData[7:0];
                end
            end
        end
    end

    /**** read Reg ****/
    wire [1:0] rPage;
    assign rPage = (intREn && ~intUsePgReg) ? {1'b0, intPageSel} : exRegFile[0][1:0];
    always @(*) begin
        if(rAddr[6:0] < 112)
            if(rPage <= 2)
                rData = regFile[rPage][rAddr[6:0]];
            else
                rData = 0;
        else
            rData = exRegFile[rAddr[3:0]];
    end

    genvar j;
    generate
        for(j = 0; j < 112; j = j + 1) begin
            assign configRegPG0[j * 8 + 7: j * 8] = regFile[0][j];
        end
        for(j = 0; j < 112; j = j + 1) begin
            assign configRegPG1[j * 8 + 7: j * 8] = regFile[1][j];
        end
        for(j = 0; j < 112; j = j + 1) begin
            assign configRegPG2[j * 8 + 7: j * 8] = regFile[2][j];
        end
        for(j = 0; j < 15; j = j + 1) begin
            assign exConfigReg[j * 8 + 7: j * 8] = exRegFile[j + 1];
        end
    endgenerate
endmodule

